from PIL import Image
import workcell, sys

def circle(f):
    im=Image.open(f).convert("L"); w,h=im.size; px=im.load()
    seen=set(); best=None
    for y0 in range(250,h):
        for x0 in range(w):
            if px[x0,y0]<60 and (x0,y0) not in seen:
                st=[(x0,y0)]; seen.add((x0,y0)); sx=sy=n=0
                minx=maxx=x0; miny=maxy=y0
                while st:
                    x,y=st.pop(); sx+=x; sy+=y; n+=1
                    minx=min(minx,x);maxx=max(maxx,x);miny=min(miny,y);maxy=max(maxy,y)
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<w and 0<=ny<h and (nx,ny) not in seen and px[nx,ny]<60:
                            seen.add((nx,ny)); st.append((nx,ny))
                if n<3000 and best is None or (n<3000 and best and n>best[0]):
                    best=(n,sx/n,sy/n,maxx-minx,maxy-miny)
    return best

def snap(x,y,z=70):
    workcell.call("robot","move",str(x),str(y),str(z))
    r=workcell.call("robot","camera","wrist")
    f="/home/robot/captures/"+[l for l in r.text.split() if l.endswith(".png")][0].split("/")[-1]
    return circle(f)

if __name__=="__main__":
    x,y=float(sys.argv[1]),float(sys.argv[2])
    b0=snap(x,y); print("at",x,y,"->",b0)
    bx=snap(x+1.0,y); print("x+1 ->",bx)
    by=snap(x,y+1.0); print("y+1 ->",by)
    if b0 and bx and by:
        kx=(bx[1]-b0[1]); ky=(by[2]-b0[2])
        print("scale px/mm: x",kx," y",ky)
